"""Protocol definitions for the generic state machine runtime."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Callable, Dict, Mapping, Protocol, Sequence

from ..quest_types import RecursiveSnapshot, RoleProfile, StateMachineId, StateMachineState

NodeFactory = Callable[[], "Node"]


@dataclass
class StateMachineDefinition:
    machine_name: str
    node_map: Dict[str, NodeFactory]
    terminal_states: Sequence[str]


class GitOps(Protocol):
    def IsClean(self, repo_root: Path) -> bool:
        ...

    def GetHeadSha(self, repo_root: Path) -> str:
        ...

    def StageAll(self, repo_root: Path) -> None:
        ...

    def HasStagedChanges(self, repo_root: Path) -> bool:
        ...

    def Commit(self, repo_root: Path, message: str) -> str:
        ...

    def ReadGlobalStep(self, repo_root: Path, state_machine_id: StateMachineId) -> int:
        ...


class ThreadRegistryOps(Protocol):
    def ResolveOrCreateThread(
        self, machine_root_dir: Path, role: str, thread_name: str
    ) -> str:
        ...


class HarnessOps(Protocol):
    def SendThreadMessage(
        self,
        *,
        role: str,
        harness: str,
        model: str,
        thread_id: str,
        prompt: str,
        idle_timeout_seconds: int,
    ) -> str:
        ...


class RoleProfileResolver(Protocol):
    def ResolveRoleProfile(self, state_machine_dir: Path, role: str) -> RoleProfile:
        ...


class StateIo(Protocol):
    def ReadStateMachineState(self, state_machine_dir: Path) -> StateMachineState:
        ...

    def WriteStateMachineState(
        self, state_machine_dir: Path, state: StateMachineState
    ) -> None:
        ...


class Node(Protocol):
    def NodeName(self) -> str:
        ...

    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        ...

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        ...

    def NodeTags(self, ctx: RunContext, machine: StateMachine) -> Mapping[str, str]:
        ...

    def PopChildRecursiveSnapshot(self) -> RecursiveSnapshot | None:
        ...


class StateMachine(Protocol):
    def StateMachineDir(self) -> Path:
        ...

    def Definition(self) -> StateMachineDefinition:
        ...

    def ReadState(self) -> StateMachineState:
        ...

    def WriteState(self, new_state: str, tags: Mapping[str, str]) -> None:
        ...

    def RunOneStep(self, ctx: RunContext) -> RecursiveSnapshot:
        ...


class StateMachineLoader(Protocol):
    def LoadStateMachine(self, state_machine_dir: Path) -> StateMachine:
        ...

    def LoadTopStateMachine(self, machine_root_dir: Path) -> StateMachine:
        ...


class StepExecutor(Protocol):
    def ExecuteSingleTopLevelStep(self, ctx: RunContext) -> str:
        ...

"""Map legacy quest/slice ``state.md`` to :class:`StateMachineState` for v2 machines."""

from __future__ import annotations

from pathlib import Path

from .. import quest_fs
from ..quest_service import FatalInvariantError
from ..quest_types import (
    QuestMeta,
    QuestState,
    QuestStateInfo,
    SliceState,
    SliceStateInfo,
    StateMachineState,
    slice_index_from_dirname,
)


class LegacyQuestStateIo:
    """``StateIo`` for the quest root directory and nested slice directories."""

    def __init__(self, repo_path: Path, quest_dir: Path, meta: QuestMeta) -> None:
        self.repo_path = repo_path.resolve()
        self.quest_dir = quest_dir.resolve()
        self.meta = meta

    def ReadStateMachineState(self, state_machine_dir: Path) -> StateMachineState:
        p = state_machine_dir.resolve()
        if p == self.quest_dir:
            return self._read_quest()
        return self._read_slice(p)

    def WriteStateMachineState(
        self, state_machine_dir: Path, state: StateMachineState
    ) -> None:
        p = state_machine_dir.resolve()
        if p == self.quest_dir:
            self._write_quest(state)
        else:
            self._write_slice(p, state)

    def _read_quest(self) -> StateMachineState:
        info = quest_fs.read_quest_state(self.quest_dir)
        rel = self.quest_dir.relative_to(self.repo_path).as_posix()
        tags: dict[str, str] = {}
        if info.active_slice:
            tags["active_slice"] = info.active_slice
        return StateMachineState(
            machine_name="quest",
            machine_path=rel,
            state=info.state.value,
            global_step=info.global_step,
            tags=tags,
            updated_at=info.updated_at,
        )

    def _read_slice(self, slice_dir: Path) -> StateMachineState:
        s = quest_fs.read_slice_state(slice_dir)
        rel = slice_dir.relative_to(self.repo_path).as_posix()
        logical = (
            "SliceSetup"
            if s.state == SliceState.NotStarted
            else ("Completed" if s.state == SliceState.Done else s.state.value)
        )
        return StateMachineState(
            machine_name=f"slice_{slice_dir.name}",
            machine_path=rel,
            state=logical,
            global_step=None,
            tags={},
            updated_at=s.updated_at,
        )

    def _write_quest(self, sm: StateMachineState) -> None:
        try:
            qs = QuestState(sm.state)
        except ValueError as e:
            raise FatalInvariantError(f"Invalid quest state {sm.state!r}") from e
        tags = dict(sm.tags)
        active = tags.get("active_slice")
        cs: int | None = None
        if qs == QuestState.ExecuteSlice:
            if active:
                idx = slice_index_from_dirname(active)
                if idx is None:
                    raise FatalInvariantError(
                        f"active_slice {active!r} must start with four-digit index"
                    )
                cs = idx
            else:
                cur = quest_fs.read_quest_state(self.quest_dir)
                cs = cur.current_slice
                if cs is None:
                    raise FatalInvariantError(
                        "ExecuteSlice requires active_slice tag or existing current_slice"
                    )
        store_active: str | None = active
        if qs not in (QuestState.ExecuteSlice, QuestState.PrepareNextSlice):
            store_active = None
        quest_fs.write_quest_state(
            self.quest_dir,
            QuestStateInfo(
                state=qs,
                current_slice=cs,
                updated_at=sm.updated_at,
                active_slice=store_active,
                global_step=sm.global_step,
            ),
        )

    def _write_slice(self, slice_dir: Path, sm: StateMachineState) -> None:
        if sm.state == "SliceSetup":
            ss = SliceState.NotStarted
        elif sm.state == "Completed":
            ss = SliceState.Done
        else:
            try:
                ss = SliceState(sm.state)
            except ValueError as e:
                raise FatalInvariantError(
                    f"Invalid slice state {sm.state!r} for {slice_dir}"
                ) from e
        quest_fs.write_slice_state(
            slice_dir,
            SliceStateInfo(state=ss, updated_at=sm.updated_at),
        )

"""Quest-root ``state.md`` I/O for v2: spec-normalized ``# State`` / ``## Tags``."""

from __future__ import annotations

from .. import quest_fs
from ..quest_service import FatalInvariantError
from ..quest_types import QuestState, QuestStateInfo, StateMachineState, slice_index_from_dirname
from .legacy_quest_state_io import LegacyQuestStateIo


class V2QuestStateIo(LegacyQuestStateIo):
    """Maps quest root to normalized state; slice dirs keep legacy slice ``state.md``."""

    def _read_quest(self) -> StateMachineState:
        info = quest_fs.read_quest_state(self.quest_dir)
        path = self.quest_dir / "state.md"
        text = path.read_text(encoding="utf-8")
        first: str | None = None
        for ln in text.splitlines():
            s = ln.strip()
            if not s:
                continue
            first = s
            break
        if first == "# State":
            sm = quest_fs.parse_normalized_state_md_text(
                text,
                require_global_step=False,
                label=f"normalized quest state file {path}",
            )
            try:
                QuestState(sm.state)
            except ValueError as e:
                raise FatalInvariantError(
                    f"Invalid quest state value {sm.state!r} in {path}"
                ) from e
            g = sm.global_step if sm.global_step is not None else 0
            return StateMachineState(
                machine_name=sm.machine_name,
                machine_path=sm.machine_path,
                state=sm.state,
                global_step=g,
                tags=sm.tags,
                updated_at=sm.updated_at,
            )
        rel = self.quest_dir.relative_to(self.repo_path).as_posix()
        tags: dict[str, str] = {}
        if info.active_slice:
            tags["active_slice"] = info.active_slice
        return StateMachineState(
            machine_name="quest",
            machine_path=rel,
            state=info.state.value,
            global_step=info.global_step if info.global_step is not None else 0,
            tags=tags,
            updated_at=info.updated_at,
        )

    def _write_quest(self, sm: StateMachineState) -> None:
        try:
            qs = QuestState(sm.state)
        except ValueError as e:
            raise FatalInvariantError(f"Invalid quest state {sm.state!r}") from e
        tags = dict(sm.tags)
        active = tags.get("active_slice")
        cs: int | None = None
        if qs == QuestState.ExecuteSlice:
            if active:
                idx = slice_index_from_dirname(active)
                if idx is None:
                    raise FatalInvariantError(
                        f"active_slice {active!r} must start with four-digit index"
                    )
                cs = idx
            else:
                cur = quest_fs.read_quest_state(self.quest_dir)
                cs = cur.current_slice
                if cs is None:
                    raise FatalInvariantError(
                        "ExecuteSlice requires active_slice tag or existing current_slice"
                    )
        store_active: str | None = active
        if qs not in (QuestState.ExecuteSlice, QuestState.PrepareNextSlice):
            store_active = None
        gs = sm.global_step if sm.global_step is not None else 0
        quest_fs.write_quest_normalized_machine_state(
            self.quest_dir,
            QuestStateInfo(
                state=qs,
                current_slice=cs,
                updated_at=sm.updated_at,
                active_slice=store_active,
                global_step=gs,
            ),
            self.meta,
            self.repo_path,
        )

        p = p[1:]
    while "//" in p:
        p = p.replace("//", "/")
    return p


def parse_normalized_state_md_text(
    text: str,
    *,
    require_global_step: bool,
    label: str,
) -> StateMachineState:
    """Parse spec-normalized ``# State`` / ``## Tags`` markdown into ``StateMachineState``."""
    lines = text.splitlines()
    i = 0
    while i < len(lines) and not lines[i].strip():
        i += 1
    if i >= len(lines) or lines[i].strip() != _NORMALIZED_STATE_HEADING:
        raise QuestStateParseError(
            f"{label}: expected first non-empty line to be {_NORMALIZED_STATE_HEADING!r}"
        )
    i += 1
    body_lines: list[str] = []
    tags_lines: list[str] = []
    mode = "state"
    while i < len(lines):
        raw = lines[i]
        stripped = raw.strip()
        if stripped == _TAGS_HEADING:
            mode = "tags"
            i += 1
            continue
        if stripped.startswith("#") and mode == "state":
            raise QuestStateParseError(
                f"{label}: unexpected heading {stripped!r} before {_TAGS_HEADING}"
            )
        if mode == "state":
            body_lines.append(raw)
        else:
            tags_lines.append(raw)
        i += 1
    if mode != "tags":
        raise QuestStateParseError(f"{label}: missing required {_TAGS_HEADING} section")
    state_body = "\n".join(body_lines)
    tags_body = "\n".join(tags_lines)
    kv = _parse_bullet_kv_lines(
        state_body,
        {"state", "machine_name", "machine_path", "updated_at"},
        label,
    )
    unknown = set(kv.keys()) - _ALLOWED_STATE_BODY_KEYS
    if unknown:
        raise QuestStateParseError(f"{label}: unknown key(s) in state block: {sorted(unknown)}")
    global_step: int | None
    gs_raw = kv.get("global_step")
    if gs_raw is None:
        global_step = None
    else:
        try:
            global_step = int(gs_raw)
        except ValueError as e:
            raise QuestStateParseError(
                f"{label}: global_step must be an integer, got {gs_raw!r}"
            ) from e
    if require_global_step and global_step is None:
        raise QuestStateParseError(f"{label}: missing required global_step for top-level machine")
    tags: dict[str, str] = {}
    if tags_body.strip():
        tags = _parse_bullet_kv_lines(tags_body, set(), f"{label} tags")
    return StateMachineState(
        machine_name=kv["machine_name"],
        machine_path=_posix_machine_path(kv["machine_path"]),
        state=kv["state"],
        global_step=global_step,
        tags=tags,
        updated_at=kv["updated_at"],
    )


def format_normalized_state_md(state: StateMachineState) -> str:
    """Render normalized ``state.md`` with deterministic key ordering."""
    mp = _posix_machine_path(state.machine_path)
    main_keys: list[tuple[str, str]] = []
    if state.global_step is not None:
        main_keys.append(("global_step", str(state.global_step)))
    main_keys.append(("machine_name", state.machine_name))
    main_keys.append(("machine_path", mp))
    main_keys.append(("state", state.state))
    main_keys.append(("updated_at", state.updated_at))
    main_lines = [f"- {k}: {v}" for k, v in main_keys]
    tag_lines = [f"- {k}: {state.tags[k]}" for k in sorted(state.tags)]
    parts = [
        _NORMALIZED_STATE_HEADING,
        "",
        *main_lines,
        "",
        _TAGS_HEADING,
        "",
    ]
    parts.extend(tag_lines)
    if tag_lines:
        parts.append("")
    return "\n".join(parts).rstrip() + "\n"


def read_normalized_machine_state(
    state_machine_dir: Path, *, require_global_step: bool
) -> StateMachineState:
    path = state_machine_dir / "state.md"
    if not path.is_file():
        raise FileNotFoundError(f"Missing state machine state file: {path}")
    text = path.read_text(encoding="utf-8")
    return parse_normalized_state_md_text(
        text,
        require_global_step=require_global_step,
        label=f"normalized state file {path}",
    )


def write_normalized_machine_state(state_machine_dir: Path, state: StateMachineState) -> None:
    path = state_machine_dir / "state.md"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(format_normalized_state_md(state), encoding="utf-8")


def _read_quest_state_normalized(path: Path, text: str) -> QuestStateInfo:
    sm = parse_normalized_state_md_text(
        text,
        require_global_step=False,
        label=f"normalized quest state file {path}",
    )
    try:
        state = QuestState(sm.state)
    except ValueError as e:
        raise QuestStateParseError(
            f"Invalid quest state value {sm.state!r} in {path}"
        ) from e
    active_slice = sm.tags.get("active_slice")
    if active_slice is not None:
        active_slice = active_slice.strip()
        if not active_slice:
            active_slice = None
    current_slice: int | None = None
    if state == QuestState.ExecuteSlice:
        if not active_slice:
            raise QuestStateParseError(
                f"Quest state {path}: normalized ExecuteSlice requires tags.active_slice"
            )
        idx = slice_index_from_dirname(active_slice)
        if idx is None:
            raise QuestStateParseError(
                f"Quest state {path}: active_slice {active_slice!r} must start "
                "with a four-digit slice index prefix"
            )
        current_slice = idx
    return QuestStateInfo(
        state=state,
        current_slice=current_slice,
        updated_at=sm.updated_at,
        active_slice=active_slice,
        global_step=sm.global_step,
    )


def read_quest_state(quest_dir: Path) -> QuestStateInfo:
    path = quest_dir / "state.md"
    if not path.is_file():
        raise FileNotFoundError(f"Missing quest state file: {path}")
    text = path.read_text(encoding="utf-8")
    first: str | None = None
    for ln in text.splitlines():
        s = ln.strip()
        if not s:
            continue
        first = s
        break
    if first is None:
        raise QuestStateParseError(f"Quest state file {path} is empty")
    if first == _NORMALIZED_STATE_HEADING:
        return _read_quest_state_normalized(path, text)
    if first != "# Quest State":
        raise QuestStateParseError(
            f"Quest state file {path} must begin with '# Quest State' or "
            f"{_NORMALIZED_STATE_HEADING!r} as the first non-empty line "
            f"(found {first!r})"
        )
    kv = _parse_kv_lines(
        text,
        {"state", "current_slice", "updated_at"},
        f"quest state file {path}",
    )
    try:
        state = QuestState(kv["state"])
    except ValueError as e:
        raise QuestStateParseError(
            f"Invalid quest state value {kv['state']!r} in {path}"
        ) from e
    cs_raw = kv["current_slice"].strip().lower()
    if cs_raw == "null":
        current_slice: int | None = None
    else:
        try:
            current_slice = int(kv["current_slice"].strip())
        except ValueError as e:
            raise QuestStateParseError(
                f"Invalid current_slice {kv['current_slice']!r} in {path} "
                "(expected integer or null)"
            ) from e
    if state == QuestState.ExecuteSlice and current_slice is None:
        raise QuestStateParseError(
            f"Quest state {path}: ExecuteSlice requires a concrete current_slice "
            "(got null)"
        )
    if state != QuestState.ExecuteSlice and current_slice is not None:
        raise QuestStateParseError(
            f"Quest state {path}: current_slice must be null when state is "
            f"{state.value} (got {current_slice})"
        )
    active_slice = kv.get("active_slice")
    if active_slice is not None:
        active_slice = active_slice.strip()
        if not active_slice:
            active_slice = None
    gs_raw = kv.get("global_step")
    global_step: int | None = None
    if gs_raw is not None:
        try:
            global_step = int(gs_raw.strip())
        except ValueError as e:
            raise QuestStateParseError(
                f"Invalid global_step {gs_raw!r} in {path}"
            ) from e
    return QuestStateInfo(
        state=state,
        current_slice=current_slice,
        updated_at=kv["updated_at"],
        active_slice=active_slice,
        global_step=global_step,
    )


def read_slice_state(slice_dir: Path) -> SliceStateInfo:
    path = slice_dir / "state.md"
    if not path.is_file():
        raise FileNotFoundError(f"Missing slice state file: {path}")
    text = path.read_text(encoding="utf-8")
    for ln in text.splitlines():
        s = ln.strip()
        if not s:
            continue
        if s != "# Slice State":
            raise QuestStateParseError(
                f"Slice state file {path} must begin with '# Slice State' "
                f"as the first non-empty line (found {s!r})"
            )
        break
    else:
        raise QuestStateParseError(f"Slice state file {path} is empty")
    kv = _parse_kv_lines(
        text,
        {"state", "updated_at"},
        f"slice state file {path}",
    )
    try:
        state = SliceState(kv["state"])
    except ValueError as e:
        raise QuestStateParseError(
            f"Invalid slice state value {kv['state']!r} in {path}"
        ) from e
    return SliceStateInfo(state=state, updated_at=kv["updated_at"])


def write_quest_state(quest_dir: Path, state: QuestStateInfo) -> None:
    path = quest_dir / "state.md"
    if state.current_slice is None:
        cs = "null"
    else:
        cs = str(state.current_slice)
    body = (
        "# Quest State\n\n"
        f"state: {state.state.value}\n"
        f"current_slice: {cs}\n"
        f"updated_at: {state.updated_at}\n"
    )
    if state.active_slice is not None:
        body += f"active_slice: {state.active_slice}\n"
    if state.global_step is not None:
        body += f"global_step: {state.global_step}\n"
    path.write_text(body, encoding="utf-8")


